$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$orch=Join-Path $root 'orchestrator.ps1';$bridge=Split-Path -Parent (Split-Path -Parent $root)
$sandbox=Join-Path $env:TEMP ('flcad-watch-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $sandbox|Out-Null
function W($p,$v){$v|ConvertTo-Json -Depth 12|Set-Content $p -Encoding UTF8}
function A([bool]$c,[string]$m){if(-not $c){throw "ASSERTION FAILED: $m"}}
function Wait-File([string]$p,[int]$seconds=20){for($i=0;$i -lt $seconds;$i++){if(Test-Path $p){return $true};Start-Sleep -Seconds 1};return $false}
function Wait-QueueState([string]$p,[string]$id,[string]$state,[int]$seconds=30){for($i=0;$i -lt $seconds;$i++){if(Test-Path $p){$q=Get-Content $p -Raw|ConvertFrom-Json;$r=$q.tasks|Where-Object task_id -eq $id;if($r.state -eq $state){return $true}};Start-Sleep -Seconds 1};return $false}
try {
  $head=(git -C $bridge rev-parse HEAD).Trim();$taskPath=Join-Path $sandbox 'task.json';$task=[ordered]@{schemaVersion='1.0';id='AB06E-WATCH-1';objective='watch synthetic environment';sourceBranch='automation/flcad-bridge';baseCommit=$head;allowedPaths=@('tools/flcad_automation');requiredTests=@('synthetic');acceptanceCriteria=@('report generated');limits=@{maxDurationSeconds=30;maxOutputBytes=1048576};permissions=@{workspaceWrite=$false;network=$false;gitMutation=$false;remotePublish=$false};state='approved';reportPath='tools/flcad_automation/watch-tests/AB06E-WATCH-1.json';action='environment'};W $taskPath $task
  $queue=Join-Path $sandbox 'queue.json';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Add -QueuePath $queue -Task $taskPath -Worktree $bridge|Out-Null;A($LASTEXITCODE -eq 0)'task must be queued'
  $task2=[ordered]@{};$task.GetEnumerator()|ForEach-Object{$task2[$_.Key]=$_.Value};$task2.id='AB06E-WATCH-2';$task2.reportPath='tools/flcad_automation/watch-tests/AB06E-WATCH-2.json';$task2Path=Join-Path $sandbox 'task2.json';W $task2Path $task2;& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Add -QueuePath $queue -Task $task2Path -Worktree $bridge|Out-Null;A($LASTEXITCODE -eq 0)'second task must be queued'
  $watchOut=Join-Path $sandbox 'watch.out';$watchErr=Join-Path $sandbox 'watch.err';$watch=Start-Process -FilePath powershell.exe -WindowStyle Hidden -PassThru -RedirectStandardOutput $watchOut -RedirectStandardError $watchErr -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$orch,'-Command','Watch','-QueuePath',$queue,'-Worktree',$bridge,'-IntervalSeconds','1')
  $heartbeat=Join-Path $sandbox 'watch-heartbeat.json';A(Wait-File $heartbeat)'heartbeat must appear';A((Wait-QueueState $queue 'AB06E-WATCH-1' 'blocked'))'human review must stop watch queue';$status=Get-Content $heartbeat -Raw|ConvertFrom-Json;$q=Get-Content $queue -Raw|ConvertFrom-Json;A($q.tasks[1].state -eq 'queued')'second task must remain queued';A($status.state -in @('running','blocked'))'watch heartbeat must be live or blocked'
  A(-not $watch.HasExited)'watch must remain available while queue is blocked';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Stop -QueuePath $queue -Worktree $bridge|Out-Null;A($LASTEXITCODE -eq 0)'blocked watch stop must succeed';$watch.WaitForExit(10000)|Out-Null;A($watch.HasExited)'stop must terminate blocked Watch'
  $emptyQueue=Join-Path $sandbox 'empty-queue.json';$watch2=Start-Process -FilePath powershell.exe -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$orch,'-Command','Watch','-QueuePath',$emptyQueue,'-Worktree',$bridge,'-IntervalSeconds','1');$emptyHeartbeat=Join-Path $sandbox 'watch-heartbeat.json';A(Wait-File $emptyHeartbeat)'second heartbeat must appear';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Pause -QueuePath $emptyQueue|Out-Null;Start-Sleep -Seconds 2;$paused=Get-Content $emptyHeartbeat -Raw|ConvertFrom-Json;A($paused.state -eq 'paused')'pause must update heartbeat';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Resume -QueuePath $emptyQueue|Out-Null;Start-Sleep -Seconds 2;$resumed=Get-Content $emptyHeartbeat -Raw|ConvertFrom-Json;A($resumed.state -eq 'running')'resume must update heartbeat';$watch3=Start-Process -FilePath powershell.exe -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$orch,'-Command','Watch','-QueuePath',$emptyQueue,'-Worktree',$bridge,'-IntervalSeconds','1');$watch3.WaitForExit(10000)|Out-Null;A($watch3.ExitCode -ne 0)'second Watch must be rejected by lock';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Stop -QueuePath $emptyQueue -Worktree $bridge|Out-Null;A($LASTEXITCODE -eq 0)'stop command must succeed';$watch2.WaitForExit(10000)|Out-Null;A($watch2.HasExited)'stop must terminate Watch'
  $flutterQueue=Join-Path $sandbox 'flutter-queue.json';$functionalHead=('0'*40);$flutterTask=[ordered]@{schemaVersion='1.0';id='AB06E-WATCH-FLUTTER';objective='guard Flutter watch isolation';sourceBranch='feat/plane-axis-intersection-point';baseCommit=$functionalHead;allowedPaths=@('test');requiredTests=@('fixed');acceptanceCriteria=@('snapshot guard');limits=@{maxDurationSeconds=30;maxOutputBytes=1048576};permissions=@{workspaceWrite=$false;network=$false;gitMutation=$false;remotePublish=$false};state='approved';reportPath='tools/flcad_automation/watch-tests/AB06E-WATCH-FLUTTER.json';action='flutter-selection-latency'};$flutterPath=Join-Path $sandbox 'flutter-task.json';W $flutterPath $flutterTask;& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Add -QueuePath $flutterQueue -Task $flutterPath -Worktree $bridge|Out-Null;$flutterWatch=Start-Process -FilePath powershell.exe -WindowStyle Hidden -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$orch,'-Command','Watch','-QueuePath',$flutterQueue,'-Worktree',$bridge,'-IntervalSeconds','1');A((Wait-File (Join-Path $sandbox 'watch-heartbeat.json')))'Flutter guard heartbeat must appear';A((Wait-QueueState $flutterQueue 'AB06E-WATCH-FLUTTER' 'blocked'))'Watch must reject divergent snapshot origin';& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Stop -QueuePath $flutterQueue -Worktree $bridge|Out-Null;$flutterWatch.WaitForExit(10000)|Out-Null;A($flutterWatch.HasExited)'Flutter guard Watch must stop'
  $recoverQueue=Join-Path $sandbox 'recover.json';$recover=[pscustomobject]@{schema_version='1.0';tasks=@([pscustomobject]@{task_id='AB06E-RECOVER';task_path=$taskPath;state='running';attempts=1})};W $recoverQueue $recover;& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $orch -Command Recover -QueuePath $recoverQueue -Worktree $bridge|Out-Null;A($LASTEXITCODE -eq 0)'recover must succeed';$recovered=Get-Content $recoverQueue -Raw|ConvertFrom-Json;A($recovered.tasks[0].state -eq 'queued')'stale running task must be recoverable'
  Write-Output 'watch.tests.ps1: PASS'
} finally {Get-Process powershell -ErrorAction SilentlyContinue|Where-Object{$_.Id -in @($watch.Id,$watch2.Id,$watch3.Id)}|Stop-Process -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath $sandbox -Recurse -Force -ErrorAction SilentlyContinue;Remove-Item -LiteralPath (Join-Path $bridge 'tools/flcad_automation/watch-tests') -Recurse -Force -ErrorAction SilentlyContinue}
